import{_ as s,o as e,c as a,an as t}from"./chunks/framework.gM3-hPsp.js";const k=JSON.parse('{"title":"Periodic Boundary Conditions","description":"","frontmatter":{},"headers":[],"relativePath":"pbc.md","filePath":"pbc.md","lastUpdated":null}'),n={name:"pbc.md"};function l(d,i,h,o,p,r){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="Periodic-Boundary-Conditions" tabindex="-1">Periodic Boundary Conditions <a class="header-anchor" href="#Periodic-Boundary-Conditions" aria-label="Permalink to &quot;Periodic Boundary Conditions {#Periodic-Boundary-Conditions}&quot;">​</a></h1><p>MicroMagnetic supports periodic boundary conditions (PBC) on any combination of the three axes. Periodicity is declared <strong>once, on the mesh</strong>, and every interaction term respects it automatically: exchange and DMI through the periodic neighbor table, and the demagnetization field through a dedicated periodic solver. This removes the silent inconsistency of &quot;periodic exchange but open demag&quot;.</p><h2 id="Declaring-periodicity" tabindex="-1">Declaring periodicity <a class="header-anchor" href="#Declaring-periodicity" aria-label="Permalink to &quot;Declaring periodicity {#Declaring-periodicity}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> FDMesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; nx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ny</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, nz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5e-9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5e-9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3e-9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pbc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>pbc</code> accepts any combination of the characters <code>&quot;x&quot;</code>, <code>&quot;y&quot;</code>, <code>&quot;z&quot;</code> (default <code>&quot;open&quot;</code>). The rest of the setup is unchanged:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh; driver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LLG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;skx_lattice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_Ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8e5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_exch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.3e-11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_dmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3e-3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interfacial&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_demag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim)                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># solver selected automatically from mesh.pbc</span></span></code></pre></div><h2 id="Demagnetization-solvers" tabindex="-1">Demagnetization solvers <a class="header-anchor" href="#Demagnetization-solvers" aria-label="Permalink to &quot;Demagnetization solvers {#Demagnetization-solvers}&quot;">​</a></h2><p>The demag solver is selected automatically from the mesh periodicity:</p><table tabindex="0"><thead><tr><th style="text-align:left;">mesh periodicity</th><th style="text-align:left;">solver</th><th style="text-align:left;">method</th><th style="text-align:left;">reference</th></tr></thead><tbody><tr><td style="text-align:left;">open</td><td style="text-align:left;">open demag</td><td style="text-align:left;">padded-FFT (or direct with <code>fft=false</code>)</td><td style="text-align:left;">Newell</td></tr><tr><td style="text-align:left;">one axis (<code>x</code>/<code>y</code>/<code>z</code>)</td><td style="text-align:left;">pbc1d</td><td style="text-align:left;">image sums + analytic tail + DC-column fix</td><td style="text-align:left;">Lebecki, <em>J. Phys. D</em> <strong>41</strong>, 175005 (2008)</td></tr><tr><td style="text-align:left;">two axes (<code>xy</code>/<code>xz</code>/<code>yz</code>)</td><td style="text-align:left;">pbc2d</td><td style="text-align:left;">image sums + analytic tail + DC-column fix</td><td style="text-align:left;">Wang et al., <em>Comp. Mater. Sci.</em> <strong>49</strong>, 84 (2010)</td></tr><tr><td style="text-align:left;">three axes (<code>xyz</code>)</td><td style="text-align:left;">pbc3d</td><td style="text-align:left;">spectral projector (tin-foil convention)</td><td style="text-align:left;">Mansuripur (1989)</td></tr></tbody></table><p>The periodic kernel is the image sum <code>N^PBC(d) = Σ_images N(d + p·L)</code>. For one and two periodic axes this sum converges absolutely, so explicit images plus a closed-form continuous tail give a well-defined approximation. For three periodic axes the sum is only conditionally convergent; pbc3d uses the standard spectral projector instead (the uniform mode carries no field).</p><h3 id="Image-counts-Ic-/-Jc" tabindex="-1">Image counts <code>Ic</code> / <code>Jc</code> <a class="header-anchor" href="#Image-counts-Ic-/-Jc" aria-label="Permalink to &quot;Image counts \`Ic\` / \`Jc\` {#Image-counts-Ic-/-Jc}&quot;">​</a></h3><p>For pbc1d/pbc2d the number of explicit images per periodic axis defaults to <code>Ic = Jc = 4</code>. Increase it for higher accuracy at linear init-cost:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_demag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim; Ic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Jc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># more images, smaller tail error</span></span></code></pre></div><p>Typical field errors against a brute-force image sum: pbc1d <code>Ic=2</code> → 6×10⁻⁵, <code>Ic=4</code> → 2.5×10⁻⁶; pbc2d <code>Ic=2</code> → 1×10⁻⁴.</p><h3 id="Legacy-explicit-macro-mode" tabindex="-1">Legacy explicit-macro mode <a class="header-anchor" href="#Legacy-explicit-macro-mode" aria-label="Permalink to &quot;Legacy explicit-macro mode {#Legacy-explicit-macro-mode}&quot;">​</a></h3><p>The legacy truncated-image macro cell mode is still available and takes precedence when its keywords are given:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_demag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim; macroPBC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Nx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Ny</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nx/Ny/Nz = repetition counts</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add_demag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim; Nx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Ny</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># legacy semantics without macroPBC</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p><code>fft=false</code> degrades to the direct solver with truncated images; true PBC requires the FFT pipeline (default).</p></div><h2 id="Consistency-guarantees" tabindex="-1">Consistency guarantees <a class="header-anchor" href="#Consistency-guarantees" aria-label="Permalink to &quot;Consistency guarantees {#Consistency-guarantees}&quot;">​</a></h2><ul><li><p>The periodic axes live on the mesh only; <code>add_exch</code>, <code>add_dmi</code> and <code>add_demag</code> all read them from <code>sim.mesh</code>. There is no per-term periodicity keyword to set.</p></li><li><p>Passing an explicit demag keyword that contradicts the mesh periodic axes (for example <code>Nx</code> on an open axis) triggers a warning. Passing them on an <strong>open</strong> mesh is silent — that is the supported way to test the legacy macro solver in isolation.</p></li><li><p>The index bookkeeping <code>indexpbc(i, j, k, nx, ny, nz, xperiodic, yperiodic)</code> wraps around periodic axes; use it instead of <code>index</code> when scanning neighbors of a periodic mesh by hand.</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Implementation notes</p><p>The math, sign conventions and verification methodology of the periodic demag solvers are documented for developers in <a href="./dev/demag">Demag Internals</a>.</p></div>`,21)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
